#!/usr/bin/env python3
"""Build the subset Material Design Icons CSS/font shipped with the cheat UI.

The plugin ships its assets locally (no CDN), so bundling all ~7000 MDI icons
would add roughly 700 KB to every install. This script keeps only the icons
that actually appear in the cheat sources and in Vuetify's bundled defaults.

Requires: pip install fonttools brotli

Typical refresh:

  curl -L -o /tmp/mdi.css https://cdn.jsdelivr.net/npm/@mdi/font@6.9.96/css/materialdesignicons.min.css
  curl -L -o /tmp/mdi.woff2 https://cdn.jsdelivr.net/npm/@mdi/font@6.9.96/fonts/materialdesignicons-webfont.woff2
  python tools/vendor/build-mdi-subset.py --mdi-css /tmp/mdi.css --mdi-font /tmp/mdi.woff2

The output paths default to cheat-engine/www/cheat/libs/mdi/.
"""

from __future__ import annotations

import argparse
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
DEFAULT_SOURCE = ROOT / "cheat-engine" / "www" / "cheat"
DEFAULT_OUTPUT_CSS = DEFAULT_SOURCE / "libs" / "mdi" / "materialdesignicons.min.css"
DEFAULT_OUTPUT_FONT = (
    DEFAULT_SOURCE / "libs" / "mdi" / "fonts" / "materialdesignicons-webfont.woff2"
)

ICON_PATTERN = re.compile(r"mdi-[a-z0-9]+(?:-[a-z0-9]+)*")
RULE_PATTERN = re.compile(r"([^{}]+)\{([^{}]*)\}")
GLYPH_PATTERN = re.compile(r'content:\s*"\\([0-9A-Fa-f]+)"')


def collect_requested_icons(source_root: Path) -> dict[str, list[str]]:
    """Map every referenced icon name to the files/lines that use it."""
    requested: dict[str, list[str]] = {}
    for path in sorted(source_root.rglob("*.js")):
        text = path.read_text(encoding="utf-8", errors="replace")
        for line_number, line in enumerate(text.splitlines(), start=1):
            for match in ICON_PATTERN.finditer(line):
                location = f"{path.relative_to(ROOT).as_posix()}:{line_number}"
                requested.setdefault(match.group(0), []).append(location)
    return requested


def parse_stylesheet(css_text: str) -> tuple[list[str], dict[str, int], str]:
    """Return base rules, icon name -> codepoint, and the upstream version."""
    base_rules: list[str] = []
    icons: dict[str, int] = {}

    for rule in RULE_PATTERN.finditer(css_text):
        selector = rule.group(1).strip()
        body = rule.group(2).strip()
        if selector.startswith("@font-face"):
            continue
        glyph = GLYPH_PATTERN.search(body)
        if glyph is None:
            if selector:
                base_rules.append(f"{selector}{{{body}}}")
            continue
        codepoint = int(glyph.group(1), 16)
        for name in re.findall(r"\.mdi-([a-z0-9-]+)", selector):
            icons[name] = codepoint

    version_match = re.search(r"materialdesignicons-webfont\.woff2\?v=([0-9.]+)", css_text)
    version = version_match.group(1) if version_match else "unknown"
    return base_rules, icons, version


def rewrite_base_rules(base_rules: list[str], version: str) -> list[str]:
    """Replace the upstream @font-face with a local woff2-only declaration."""
    font_face = (
        "@font-face{"
        'font-family:"Material Design Icons";'
        f'src:url("fonts/materialdesignicons-webfont.woff2?v={version}") format("woff2");'
        "font-weight:normal;font-style:normal}"
    )
    return [font_face, *base_rules]


def build_stylesheet(
    base_rules: list[str],
    icons: dict[str, int],
    used_names: list[str],
    version: str,
) -> str:
    header = (
        "/*! Material Design Icons "
        f"v{version} - subset of {len(used_names)} icons "
        "generated by tools/vendor/build-mdi-subset.py */\n"
    )
    rules = rewrite_base_rules(base_rules, version)
    for name in sorted(used_names):
        rules.append(f'.mdi-{name}::before{{content:"\\{icons[name]:X}"}}')
    return header + "\n".join(rules) + "\n"


def write_font(source_font: Path, output_font: Path, codepoints: list[int]) -> None:
    output_font.parent.mkdir(parents=True, exist_ok=True)
    unicodes = ",".join(f"U+{codepoint:X}" for codepoint in codepoints)
    command = [
        sys.executable,
        "-m",
        "fontTools.subset",
        str(source_font),
        f"--unicodes={unicodes}",
        "--flavor=woff2",
        "--no-hinting",
        f"--output-file={output_font}",
    ]
    subprocess.run(command, check=True)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--mdi-css", required=True, type=Path)
    parser.add_argument("--mdi-font", required=True, type=Path)
    parser.add_argument("--source", type=Path, default=DEFAULT_SOURCE)
    parser.add_argument("--output-css", type=Path, default=DEFAULT_OUTPUT_CSS)
    parser.add_argument("--output-font", type=Path, default=DEFAULT_OUTPUT_FONT)
    args = parser.parse_args()

    requested = collect_requested_icons(args.source)
    if not requested:
        print("No mdi-* references found", file=sys.stderr)
        return 1

    css_text = args.mdi_css.read_text(encoding="utf-8")
    base_rules, icons, version = parse_stylesheet(css_text)

    missing = sorted(name for name in requested if name[4:] not in icons)
    if missing:
        print("Icons are not available in this MDI release:", file=sys.stderr)
        for name in missing:
            for location in requested[name]:
                print(f"  {location}: {name}", file=sys.stderr)
        return 1

    used_names = sorted(name[4:] for name in requested)
    css_output = build_stylesheet(base_rules, icons, used_names, version)
    args.output_css.parent.mkdir(parents=True, exist_ok=True)
    args.output_css.write_text(css_output, encoding="utf-8", newline="\n")

    codepoints = sorted({icons[name] for name in used_names})
    write_font(args.mdi_font, args.output_font, codepoints)

    print(
        f"MDI v{version}: {len(used_names)} icons, "
        f"CSS {args.output_css.stat().st_size} bytes, "
        f"font {args.output_font.stat().st_size} bytes"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
